const event = $input.first().json;
const type = event.type || 'unknown';
let summary = '';
let severity = 'medium';

if (type === 'posthog_error_spike') {
  summary = `Error spike detected: ${event.error_count || 'N/A'} errors in the last hour (${event.error_type || 'mixed'} errors). Affected: ~${event.affected_users || 'unknown'} users.`;
  severity = (event.error_count || 0) > 50 ? 'high' : 'medium';
} else if (type === 'railway_deploy_fail') {
  summary = `Deploy failed on ${event.service_name || 'unknown service'}. Error: ${event.error_message || 'unknown'}. Environment: ${event.environment || 'production'}.`;
  severity = 'high';
} else {
  summary = `Alert: ${event.message || JSON.stringify(event).slice(0, 200)}`;
}

return [{ json: { summary, severity, type, raw: event } }];

